case 'tourl3': {
    await bulter.sendMessage(m.chat, { react: { text: '⏳', key: m.key } })
    try {
        let q = m.quoted ? m.quoted : m
        let mime = (q.msg || q).mimetype || ''
        if (!mime) return reply('Kirim foto/video atau reply media dengan perintah .tourl')

        let media = await bulter.downloadMediaMessage(q)
        if (!media) return reply('Gagal mengunduh media')

        let base64Data = `data:${mime};base64,${media.toString('base64')}`
        let extension = mime.split('/')[1]
        let fileName = `WA-Upload-${Date.now()}.${extension}`

        const response = await axios.post('https://wanzofc.site/api/upload', {
            filename: fileName,
            contentType: mime,
            base64: base64Data,
            description: "Upload Bot",
            parentId: null
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': 'wu_67ad1ff844bf7a195035dd401d9d964aa8e74e4085c49ff1'
            }
        })

        if (response.data && response.data.url) {
            let caption = `*UPLOAD BERHASIL*\n\n`
            caption += `*◦ Nama:* ${response.data.filename || fileName}\n`
            caption += `*◦ Ukuran:* ${response.data.size || 'Unknown'}\n`
            caption += `*◦ Link:* ${response.data.url}\n\n`
            caption += `_File akan tersimpan secara permanen di akun W-Upload._`
            reply(caption)
        } else {
            reply('Gagal mendapatkan respon URL dari server.')
        }
    } catch (e) {
        console.error(e)
        reply(`Terjadi kesalahan saat upload: ${e.message}`)
    }
}
